// comment-thread moderation feature — inline edit, tombstones, pinned marker.
//
// Injected into the base with `moderation={commentModeration}` (CommentThreadProps — see
// `../../hooks/use-moderation-extension.ts`). Ships as its own registry item,
// `@ilinxa/comment-thread-moderation`, which depends on `@ilinxa/comment-thread`. The base never
// imports this folder.

import type { CommentModerationExtension } from "../../types";
import { CommentEditComposer } from "./parts/edit-composer";
import { CommentPinnedMarker } from "./parts/pinned-marker";
import { CommentTombstone } from "./parts/tombstone";

/** Pass straight through: `<CommentThread moderation={commentModeration} />`. */
export const commentModeration: CommentModerationExtension = {
  EditComposer: CommentEditComposer,
  Tombstone: CommentTombstone,
  PinnedMarker: CommentPinnedMarker,
};

export { CommentEditComposer } from "./parts/edit-composer";
export { CommentTombstone } from "./parts/tombstone";
export { CommentPinnedMarker } from "./parts/pinned-marker";

// @ilinxa/comment-thread-moderation 0.5.0

"use client";

import { memo, useEffect, useMemo, useRef } from "react";
import {
  CommentComposer,
  type CommentComposerHandle,
} from "../../../parts/comment-composer";
import type { CommentEditComposerProps } from "../../../types";

/**
 * Inline editor that replaces a comment's body. Reuses the thread's composer: the text starts as
 * the comment's content, Save posts it, Cancel and Escape leave it, and a rejected save keeps the
 * text and shows `labels.editFailed` in a `role="alert"` line (the composer owns that failure UI).
 */
function CommentEditComposerInner({
  comment,
  labels,
  onSave,
  onCancel,
  submitOnEnter,
  minRows,
  maxRows,
  className,
}: CommentEditComposerProps) {
  const composerLabels = useMemo(
    () => ({
      composerPlaceholder: labels.edit,
      composerSend: labels.save,
      composerCancel: labels.composerCancel,
      postFailed: labels.editFailed,
    }),
    [labels.edit, labels.save, labels.composerCancel, labels.editFailed],
  );

  // The Edit item lives in a menu that hands focus back to its trigger a beat after it closes,
  // which is after the editor mounts. Keep the caret in the editor: focus it, and take focus
  // back once if it lands outside the editor right after.
  const hostRef = useRef<HTMLDivElement>(null);
  const composerRef = useRef<CommentComposerHandle>(null);
  useEffect(() => {
    const focusEditor = () => composerRef.current?.focus();
    const first = setTimeout(focusEditor, 0);
    const reclaim = (event: FocusEvent) => {
      const host = hostRef.current;
      if (host && event.target instanceof Node && !host.contains(event.target)) focusEditor();
    };
    document.addEventListener("focusin", reclaim);
    const stop = setTimeout(() => document.removeEventListener("focusin", reclaim), 300);
    return () => {
      clearTimeout(first);
      clearTimeout(stop);
      document.removeEventListener("focusin", reclaim);
    };
  }, []);

  return (
    <div ref={hostRef} className={className}>
      <CommentComposer
        ref={composerRef}
        initialValue={comment.content}
        onSubmit={onSave}
        onCancel={onCancel}
        submitOnEnter={submitOnEnter}
        minRows={minRows}
        maxRows={maxRows}
        labels={composerLabels}
        ariaLabel={labels.edit}
        autoFocus
      />
    </div>
  );
}

export const CommentEditComposer = memo(CommentEditComposerInner);
CommentEditComposer.displayName = "CommentEditComposer";

"use client";

import { memo } from "react";
import { Pin } from "lucide-react";
import { cn } from "@/lib/utils";
import type { CommentPinnedMarkerProps } from "../../../types";

/** The "Pinned" marker shown beside a pinned comment's author name. */
function CommentPinnedMarkerInner({ labels, className }: CommentPinnedMarkerProps) {
  return (
    <span
      className={cn(
        "inline-flex items-center gap-1 text-xs font-medium text-muted-foreground",
        className,
      )}
    >
      <Pin className="h-3 w-3" aria-hidden="true" />
      {labels.pinned}
    </span>
  );
}

export const CommentPinnedMarker = memo(CommentPinnedMarkerInner);
CommentPinnedMarker.displayName = "CommentPinnedMarker";

"use client";

import { memo } from "react";
import { cn } from "@/lib/utils";
import type { CommentTombstoneProps } from "../../../types";

/** Stands in for a deleted, hidden or removed comment; its replies render below it. */
function CommentTombstoneInner({ state, labels, className }: CommentTombstoneProps) {
  return (
    <p
      data-comment-state={state}
      className={cn(
        "rounded-xl bg-muted/30 px-3 py-2 text-sm italic text-muted-foreground",
        className,
      )}
    >
      {labels.tombstone(state)}
    </p>
  );
}

export const CommentTombstone = memo(CommentTombstoneInner);
CommentTombstone.displayName = "CommentTombstone";
